export const extractDestination = (message: string) => {
  const destination = message.trim();
  if (!destination) {
    throw new Error('destination is required');
  }
  return destination;
};

export const startRunRequestSchema = z.object({
  destination: z.string().trim().min(1, 'destination is required'),
  message: z.string().trim().min(1)
});

const [destination, setDestination] = useState('');
const submit = () => startRun({ destination, message });
return <input value={destination} onChange={event => setDestination(event.target.value)} />;

app.post('/runs', async (request, response) => {
  const body = startRunRequestSchema.parse(request.body);
  return response.json(await service.start(body));
});

def login(payload):
    email = payload.get('email')
    password = payload.get('password')
    user = users.find_by_email(email)
    return create_session(user, password)

class LoginRequest(BaseModel):
    email: str
    password: str

def test_login_rejects_missing_email(client):
    response = client.post('/login', json={'password': 'secret'})
    assert response.status_code == 400

def create_payment(payload):
    amount = payload['amount']
    return gateway.charge(amount)

def approval_gate_node(state):
    if not state.get('approved'):
        return {'run_summary': {'status': 'awaiting_approval'}}
    return {'run_summary': {'status': 'approved'}}

def commit(self, message, files):
    self._run(['git', 'add', *files])
    self._run(['git', 'commit', '-m', message])
    return self.head_sha()

def run_eval_case(path):
    case = load_eval_case(path)
    result = build_workflow().invoke({'issue': case.issue})
    return evaluate_result(case, result)
